public:	TrapPatch();		short PatchTrap(unsigned short theTrapNum, void* theRoutine);		// PatchTrap patches the given trap to theRoutine. 		void LookupOldTrapAddress(short theTrapNum);		TrapPatchPtr GetPreviousPatchPtr();	TrapPatchPtr GetNewerPatchPtr();	void UnpatchTrap();		// UnpatchTrap unpatches the given trap.		static void UnpatchAll();		// UnpatchAll unpatches all traps.		UniversalProcPtr GetOldTrapAddr()	{ return oldTrapAddr; }  protected:	//----------------------------------------------------------------------------------------	// The following variable is really private but is in the interface just in case you're	// doing something really weird and you really need it	//----------------------------------------------------------------------------------------		static TrapPatchPtr pPatchList;}; #if q68K//----------------------------------------------------------------------------------------// CallBack//----------------------------------------------------------------------------------------#if PRAGMA_STRUCT_ALIGN#pragma options align=mac68k#endifstruct CallBack{	short saveRtnAdd;							// Internal use	short moveRefCon;							// Internal use	long refCon;								// the refCon that will be passed as last                                                // parm	short targOffset;							// Internal use	short jmpInst;								// Internal use	void* jmpTarg;								// Internal use};#if PRAGMA_STRUCT_ALIGN#pragma options align=reset#endiftypedef CallBack* CallBackPtr;#endif#if q68K//----------------------------------------------------------------------------------------// JmpInstructionTemplate: template for creating/patching JMP instructions.//----------------------------------------------------------------------------------------#if PRAGMA_STRUCT_ALIGN#pragma options align=mac68k#endifstruct JmpInstructionTemplate {	short			Jmp;			// jmp instruction	void*			Routine;		// address to jump to};#if PRAGMA_STRUCT_ALIGN#pragma options align=reset#endif#endif//----------------------------------------------------------------------------------------// External function declarations//----------------------------------------------------------------------------------------EXPORT_MA void FlushCache();	// Flush the data and instruction cache.	#if q68KEXPORT_MA void PatchJmpInstruction(void* patchAddress, void* jumpAddress);	// Place a 'jmp jumpAddress' instruction at patchAddress.#endif#if q68KEXPORT_MA void SetCallBack(void* targProc, long itsRefCon, CallBackPtr theCallBackPtr);	// Prepares a call back record for use. Stuffs in the target of the call back and the    // refcon to pass as an _additional_ and _last_ parameter to it. Useful for getting    // context when being called back from the toolBox. Also useful for avoiding use of    // globals when getting context.#endifinline void UnpatchAll(){	TrapPatch::UnpatchAll();}	// UnpatchAll unpatches all traps.#endif	// non-Carbon#endif	// __UPATCH__/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		----- R10 -----		 3/07/96	Removed more gratuitous inlining.		----- 3.3b1 -----		 6/22/94	Remove HeadPatch, Head1Patch and TailPatch. It is now 							up to the code in the patch to call or jump to the old							function. Remove jmpPtr and AllocBlock. 		 6/16/94	Experimental version: Make functions members of class							TrapPatch. */